async function init(){document.documentElement.classList.toggle('dark',(localStorage.getItem('scSuperTheme')||'light')==='dark');if(!token){location.replace('index.html');return}const m=MODULES.find(x=>x.id===section);if(!m){location.replace('index.html');return}title.textContent=m.title;subtitle.textContent=m.title+' Management';addBtn.style.display=['contacts','pathology','medicineOrders','adminNotifications','users','settings'].includes(section)?'none':'inline-block';/* Persistent login: module network errors never clear the saved admin token. */if(section==='doctors'){try{const hc=JSON.parse(localStorage.getItem('scAdminCache:healthcare')||'[]');facilityOptions=(Array.isArray(hc)?hc:[]).filter(x=>!isPending(x)).map(x=>({v:idOf(x),t:(x['Facility Name']||x['Hospital Name']||x.Name||idOf(x))}))}catch(e){}}loadData()}
async function loadData(background){const ck='scAdminCache:'+section;let had=false;try{const c=JSON.parse(localStorage.getItem(ck)||'null');if(Array.isArray(c)){rows=c;had=true;render()}}catch(_){}if(had&&!background)return;if(!had&&!background){content.className='empty';content.textContent=navigator.onLine?'Loading...':'No offline data yet. Connect once to sync all Admin modules.'}if(!navigator.onLine)return;try{if(!had){const all=await post({action:'adminDataAll',token}),data=all&&all.data||{};Object.keys(data).forEach(k=>{if(Array.isArray(data[k]))try{localStorage.setItem('scAdminCache:'+k,JSON.stringify(data[k]))}catch(_){}});rows=Array.isArray(data[section])?data[section]:[];render()}else{const r=await post({action:'adminData',section,token});rows=Array.isArray(r.data)?r.data:[];try{localStorage.setItem(ck,JSON.stringify(rows))}catch(_){}render()}}catch(e){if(!had&&!rows.length)content.textContent=e.message}}

function adminTimeValue(v){
  let s=String(v==null?'':v).trim();
  let m=s.match(/(?:T|\s)(\d{1,2}):(\d{2})/)||s.match(/^(\d{1,2}):(\d{2})/);
  if(!m)return ''; return String(+m[1]).padStart(2,'0')+':'+m[2];
}
function adminDisplayValue(col,v){
  if(String(col).toLowerCase().includes('time') && !String(col).toLowerCase().includes('timestamp')){
    const z=adminTimeValue(v); if(z){let [h,m]=z.split(':').map(Number),ap=h>=12?'PM':'AM';h=h%12||12;return String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+' '+ap;}
  }
  return v==null?'':v;
}
function render(){if(!rows.length){content.className='empty';content.textContent='No records found.';return}const cols=[...new Set(rows.flatMap(r=>Object.keys(r)))].filter(c=>!String(c).startsWith('_')&&!['Password Salt','Password Hash'].includes(c));let h='<div class="tablewrap"><table><thead><tr>'+cols.map(c=>'<th>'+esc(c)+'</th>').join('')+'<th>Actions</th></tr></thead><tbody>';rows.forEach((r,i)=>{const pending=isPending(r);h+='<tr>'+cols.map(c=>{const dv=adminDisplayValue(c,r[c]);return '<td title="'+esc(dv)+'">'+esc(dv)+'</td>'}).join('')+'<td><div class="rowacts">'+(pending?'<button class="green" onclick="decide('+i+',\'approve\')">Approve</button><button class="orange" onclick="decide('+i+',\'reject\')">Reject</button>':'')+((section==='changeMakers'&&!pending)?'<button class="orange" onclick="notifyCity('+i+')">Notify City Connect</button>':'')+(qrSection(section)?'<button class="green" onclick="generateQrSticker('+i+')">QR Sticker</button>':'')+'<button class="blue" onclick="openForm('+i+')">Edit</button><button class="red" onclick="removeRow('+i+')">Delete</button></div></td></tr>'});h+='</tbody></table></div>';content.className='';content.innerHTML=h;if(section==='adminNotifications'&&q.get('requestId')){const rid=q.get('requestId');const n=rows.find(x=>String(x['Request ID']||'')===rid);if(n)openNotificationDetail(n)}}


function scResolveImage(value){
 let v=String(value||'').trim();if(!v)return '';
 if(v.indexOf('data:image/')===0||v.indexOf('blob:')===0)return v;
 if(v.indexOf('//')===0)return 'https:'+v;
 if(v.indexOf('http://')===0||v.indexOf('https://')===0){
  let m=v.match(/drive[.]google[.]com[/]file[/]d[/]([^/?#]+)/i)||v.match(/[?&]id=([^&#]+)/i);
  if(m&&m[1])return 'https://drive.google.com/thumbnail?id='+encodeURIComponent(m[1])+'&sz=w1600';
  return v;
 }
 if(/^[A-Za-z0-9_-]{20,}$/.test(v))return 'https://drive.google.com/thumbnail?id='+encodeURIComponent(v)+'&sz=w1600';
 if(/[.](png|jpg|jpeg|webp|gif|svg)([?].*)?$/i.test(v))return v;
 return '';
}
function scRecordImage(r){
 const p=['Image URL','Photo URL','Profile Image','Business Image','Shop Image','Logo','Logo URL','Facility Image','School Image','Place Image','Photo','Image','Profile Photo','Provider Photo','Advertisement Image','Banner Image'];
 for(const k of p){const u=scResolveImage(r&&r[k]);if(u)return u}
 for(const k of Object.keys(r||{})){if(/image|photo|logo|picture|banner/i.test(k)){const u=scResolveImage(r[k]);if(u)return u}}
 return '';
}
function qrSection(sec){return ['businesses','education','healthcare','places','governmentOffices','services'].includes(sec)}
function qrRecordName(r){
 const keys={businesses:['Business Name','Name'],services:['Service Person Name','Provider Name','Name'],education:['Institution Name','School Name','Name'],healthcare:['Facility Name','Hospital Name','Clinic Name','Name'],places:['Place Name','Name'],governmentOffices:['Office Name','Name']}[section]||['Name'];
 for(const k of keys)if(r&&r[k])return String(r[k]);return section==='businesses'?'Sursand Connect Shop':'Sursand Connect Place'
}
function scQrUrl(r){
 const id=idOf(r);if(!id)return '';
 const type={businesses:'business',services:'service',education:'education',healthcare:'healthcare',places:'place',governmentOffices:'government'}[section]||section;
 return 'https://sursandconnect.github.io/Main-Web-App/qr.html?t='+encodeURIComponent(type)+'&id='+encodeURIComponent(id)
}
function scQrImage(url){return 'https://api.qrserver.com/v1/create-qr-code/?size=900x900&margin=22&data='+encodeURIComponent(url)}
