function schema(){return SCHEMAS[section]||[]}
async function adminPickContact(btn){ return; }
window.SCReceiveContact=function(field,number){window.scReceiveContact(field,number)};
window.scReceiveContact=function(field,number){const n=document.getElementById(String(field))||form.querySelector('[name="'+String(field).replace(/"/g,'')+'"]');if(n)n.value=String(number||'').replace(/[^+0-9]/g,'')};
function fieldHtml(def,val){const req=def.required?' required':'';const ro=def.readonly?' readonly':'';const full=def.full?' full':'';const v=val!=null&&val!==''?val:(def.default||'');if(def.type==='time')val=adminTimeValue(v);if(def.type==='select')return `<div class="field${full}"><label>${esc(def.label)}${def.required?' *':''}</label><select name="${esc(def.name)}"${req}>${(def.options||[]).map(o=>`<option value="${esc(o)}" ${String(v)===String(o)?'selected':''}>${esc(o||'Select')}</option>`).join('')}</select></div>`;if(def.type==='textarea')return `<div class="field${full}"><label>${esc(def.label)}${def.required?' *':''}</label><textarea name="${esc(def.name)}"${req}>${esc(v)}</textarea></div>`;if(def.type==='location')return `<div class="field${full}"><label>${esc(def.label)}</label><input type="hidden" name="${esc(def.name)}" value="${esc(v)}"><div class="adminLoc"><button type="button" class="small green" onclick="detectAdminLocation(this)">📍 Detect Location</button><button type="button" class="small blue" onclick="selectAdminLocation(this)">🗺️ Select Location</button><small>${esc(v)}</small></div></div>`;if(def.type==='image')return `<div class="field${full}"><label>${esc(def.label)}</label>${v?`<img src="${esc(v)}" alt="" style="width:76px;height:76px;object-fit:cover;border-radius:14px;border:1px solid var(--border);margin-bottom:5px">`:''}<input type="file" name="__image" accept="image/*"><small style="font-size:8px;color:var(--muted)">Upload image or open camera. Existing image remains if no new image is selected.</small></div>`;if(def.type==='facility'){const opts=facilityOptions.map(o=>`<option value="${esc(o.v)}" ${String(v)===String(o.v)?'selected':''}>${esc(o.t)}</option>`).join('');return `<div class="field${full}"><label>${esc(def.label)} *</label><select name="${esc(def.name)}" required><option value="">Select Healthcare Facility</option>${opts}</select></div>`}if(def.type==='stops')return `<div class="field full"><label>${esc(def.label)}</label><div class="stopbox"><div id="stopRows"></div><button class="small green" type="button" onclick="addStop()">＋ Add Stoppage</button></div></div>`;const isPhone=/(phone|mobile|whatsapp|contact number|helpline|alternate number)/i.test(String(def.name)+' '+String(def.label));return `<div class="field${full}"><label>${esc(def.label)}${def.required?' *':''}</label><div style="display:flex;gap:6px"><input style="flex:1" type="${def.type||'text'}" name="${esc(def.name)}" value="${esc(def.type==='time'?adminTimeValue(v):v)}"${req}${ro}></div></div>`}
function openForm(i){editing=i==null?null:rows[i];formTitle.textContent=editing?'Edit '+title.textContent:'Add '+title.textContent;let defs=schema().slice();
if(!defs.length){toastMsg('This module is view-only.',true);return}form.innerHTML=defs.map(d=>fieldHtml(d,editing?editing[d.name]:'')).join('')+'<button class="save" type="submit">'+(editing?'Save Changes':'Add Record')+'</button>';formModal.classList.add('active');if(section==='transport'){const stops=splitList(editing&&(editing['Stop Names']||editing.Stoppages||'')),stopsHi=splitList(editing&&(editing['Stop Names Hindi']||editing['Stoppages Hindi']||'')),times=splitList(editing&&(editing['Arrival Times']||'')),fares=splitList(editing&&(editing['Fare Details']||''));if(stops.length)stops.forEach((x,j)=>addStop(x,stopsHi[j]||'',times[j]||'',fares[j]||''));else addStop()}}
function splitList(v){return String(v||'').split(/[;|\n]+/).map(x=>x.trim()).filter(Boolean)}function addStop(name='',nameHi='',time='',fare=''){const row=document.createElement('div');row.className='stoprow';row.innerHTML=`<input class="stopName" placeholder="Stoppage" value="${esc(name)}"><input class="stopNameHi" placeholder="ठहराव (हिन्दी)" value="${esc(nameHi)}"><input class="stopTime" type="time" value="${esc(adminTimeValue(time))}"><input class="stopFare" placeholder="Fare" value="${esc(fare)}"><button type="button" onclick="this.parentElement.remove()">×</button>`;stopRows.appendChild(row)}
function fileData(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
async function saveForm(e){e.preventDefault();if(!await askConfirm(editing?'Save Changes':'Add Record',editing?'Save these changes?':'Add this record?',editing?'Save':'Add'))return false;const data={};for(const [k,v] of new FormData(form).entries()){if(k!=='__image')data[k]=v}if(section==='transport'){
  const type=String(data['Vehicle Type']||'').toLowerCase();
  const isBus=type.includes('bus');
  const normalize=v=>{
    let s=String(v||'').trim().toUpperCase(),m=s.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/);
    if(m){let h=+m[1];if(m[3]==='PM'&&h<12)h+=12;if(m[3]==='AM'&&h===12)h=0;return String(h).padStart(2,'0')+':'+m[2];}
    m=s.match(/^(\d{1,2}):(\d{2})/);
    if(m)return String(+m[1]).padStart(2,'0')+':'+m[2];
    return adminTimeValue(s);
  };
  if(isBus){
    const start=(data['Starting Point']||'Sursand').trim()||'Sursand';
    const end=(data['End Point']||data.Destination||'').trim();
    let ns=[...document.querySelectorAll('.stopName')].map(x=>x.value.trim()).filter(Boolean);
    let nsh=[...document.querySelectorAll('.stopNameHi')].map(x=>x.value.trim());
    let ts=[...document.querySelectorAll('.stopTime')].map(x=>normalize(x.value));
    let fs=[...document.querySelectorAll('.stopFare')].map(x=>x.value.trim());
    if(end && (!ns.length || ns[ns.length-1].toLowerCase()!==end.toLowerCase())){
      ns.push(end);ts.push('');fs.push('');
    }
    data['Starting Point']=start;
    data['End Point']=end;
    data.Destination=end;
    data['Route Name']=start+'-'+end;
    data['Departure Time']=normalize(data['Departure Time']);
    data['Stop Names']=ns.join(' | ');
    data['Stop Names Hindi']=nsh.slice(0,ns.length).join(' | ');
    let arrTimes=ts.slice(0,ns.length).join(' | '), fareDetails=fs.slice(0,ns.length).join(' | ');
    if(editing && !arrTimes.replace(/[ |]/g,'') && editing['Arrival Times']) arrTimes=editing['Arrival Times'];
    if(editing && !fareDetails.replace(/[ |]/g,'') && editing['Fare Details']) fareDetails=editing['Fare Details'];
    data['Arrival Times']=arrTimes;
    data['Fare Details']=fareDetails;
  }else{
    data['Starting Point']='';
    data['End Point']='';
    data.Destination='';
    data['Route Name']='';
    data['Departure Time']='';
    data['Stop Names']='';
    data['Stop Names Hindi']='';
    data['Arrival Times']='';
    data['Fare Details']='';
  }
}const image=form.querySelector('input[name="__image"]');if(image&&image.files&&image.files[0]){const file=image.files[0];data.imageBase64=await fileData(file);data.imageName=file.name;data.imageMimeType=file.type;data.__imageTarget=(schema().find(x=>x.type==='image')||{name:'Image URL'}).name}try{const original=editing?Object.assign({},editing):null;const r=await post({action:'adminSave',section,operation:editing?'edit':'add',id:editing?idOf(editing):'',originalRecord:original,data,token});formModal.classList.remove('active');const wasEditing=!!editing;if(wasEditing&&original){const pos=rows.indexOf(editing),merged=Object.assign({},original,data);if(pos>=0)rows[pos]=merged}else if(r.data&&r.data.record){rows.unshift(r.data.record)}editing=null;try{localStorage.setItem('scAdminCache:'+section,JSON.stringify(rows))}catch(_){}render();toastMsg((r.data&&r.data.message)||(wasEditing?'Changes saved successfully.':'Saved successfully.'));setTimeout(()=>loadData(true),120)}catch(err){toastMsg(err.message,true)}return false}
async function decide(i,op){if(!await askConfirm(op==='approve'?'Approve Request':'Reject Request',op==='approve'?'Approve and publish this request?':'Reject and remove this request?',op==='approve'?'Approve':'Reject'))return;try{const r=await post({action:'adminUpdate',section,operation:op,id:idOf(rows[i]),token});detailModal.classList.remove('active');toastMsg((r.data&&r.data.message)||(op==='approve'?'Approved successfully.':'Rejected successfully.'));await loadData()}catch(e){toastMsg(e.message,true)}}
async function removeRow(i){if(!await askConfirm('Delete Record','Permanently delete this record?','Delete'))return;try{const r=await post({action:'adminUpdate',section,operation:'delete',id:idOf(rows[i]),token});toastMsg((r.data&&r.data.message)||'Deleted successfully.');await loadData()}catch(e){toastMsg(e.message,true)}}
async function notifyCity(i){if(!await askConfirm('Notify City Connect','Publish a welcome banner for this Change Maker?','Notify'))return;try{const r=await post({action:'adminNotifyChangeMakerWelcome',token,memberId:idOf(rows[i])});toastMsg((r.data&&r.data.message)||'Welcome notification published successfully.')}catch(e){toastMsg(e.message,true)}}
function openNotificationDetail(n){const rid=String(n['Request ID']||''),typ=String(n['Request Type']||n.Title||'').toLowerCase();let sec=typ.includes('change')||typ.includes('join')?'changeMakers':typ.includes('service')?'services':typ.includes('business')?'businesses':'';detailTitle.textContent=n.Title||'Request Details';if(!sec){detailBody.innerHTML=`<div class="detail"><small>Message</small><b>${esc(n.Message||'')}</b></div>`;detailModal.classList.add('active');return}post({action:'adminData',section:sec,token}).then(r=>{const list=Array.isArray(r.data)?r.data:[],rec=list.find(x=>String(idOf(x))===rid);if(!rec)throw Error('Request is no longer available.');const fields=Object.keys(rec).filter(k=>!String(k).startsWith('_')).map(k=>`<div class="detail"><small>${esc(k)}</small><b>${esc(rec[k])}</b></div>`).join('');detailBody.innerHTML=`<div class="detailgrid">${fields}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px"><button class="small green" onclick="detailDecision('${sec}','${esc(idOf(rec))}','approve')">Approve</button><button class="small red" onclick="detailDecision('${sec}','${esc(idOf(rec))}','reject')">Reject</button></div>`;detailModal.classList.add('active')}).catch(e=>toastMsg(e.message,true))}
async function detailDecision(sec,id,op){if(!await askConfirm(op==='approve'?'Approve Request':'Reject Request',op==='approve'?'Approve and publish this request?':'Reject and remove this request?',op==='approve'?'Approve':'Reject'))return;try{const r=await post({action:'adminUpdate',section:sec,operation:op,id,token});detailModal.classList.remove('active');toastMsg((r.data&&r.data.message)||(op==='approve'?'Approved successfully.':'Rejected successfully.'));await loadData()}catch(e){toastMsg(e.message,true)}}
